from fabric import task

from benchmark.instance import InstanceManager
from benchmark.local import LocalBench
from benchmark.plot import Plotter, PlotError
from benchmark.remote import Bench, BenchError
from benchmark.utils import Print


nodes = 10

@task
def remote(ctx, debug=False):
    ''' Run benchmarks on AWS '''
    assert nodes % 3 == 1
    bench_params = {
        'faults': 0,
        'nodes': nodes,
        'runs': 1,
        'kappa': 4,
        'duration': 40, # + 20 ms
    }
    dkg_params = {
        'delta': 10,
        'epsilon': 19999, # n=10,19999 n=31,6451 n=64,3124 n=100,1999 n=121,1652
        'tri': 100000,
        'hr_batch': 40,
        'hr_freq': 20,
        'trans_delay': 0  # ms
    }
    try:
        Bench(ctx).run(bench_params, dkg_params, debug, True, True)
    except BenchError as e:
        Print.error(e)

@task
def remote_log(ctx, debug=False):
    ''' Run benchmarks on AWS '''
    assert nodes % 3 == 1
    bench_params = {
        'faults': 0,
        'nodes': nodes,
        'runs': 1,
        'kappa': 15,
        'duration': 60, # + 20 ms
    }
    dkg_params = {
        'delta': 10,
        'epsilon': 1652, # n=10,19999 n=31,6451 n=64,3124 n=100,1999 n=121,1652
        'tri': 100000,
        'hr_batch': 40,
        'hr_freq': 20,
        'trans_delay': 2000  # ms
    }
    try:
        Bench(ctx).run_log(bench_params, dkg_params, debug, False, False)
    except BenchError as e:
        Print.error(e)

@task
def local(ctx, debug=True):
    assert nodes % 3 == 1
    ''' Run benchmarks on localhost '''
    bench_params = {
        'faults': 0,
        'nodes': nodes,
        'kappa': 2,
        'duration': 20,
    }
    dkg_params = {
        'delta': 10,
        'epsilon': 19999,
        'tri': 100000,
        'hr_batch': 40,
        'hr_freq': 20,
        'trans_delay': 0 # ms
    }
    try:
        ret = LocalBench(bench_params, dkg_params).run(debug)
        print(ret.result())
    except BenchError as e:
        Print.error(e)



@task
def create(ctx, nodes=90):
    ''' Create a testbed'''
    try:
        InstanceManager.make().create_instances(nodes + 1)
    except BenchError as e:
        Print.error(e)


@task
def destroy(ctx):
    ''' Destroy the testbed '''
    try:
        InstanceManager.make().terminate_instances()
    except BenchError as e:
        Print.error(e)


@task
def start(ctx, max=nodes):
    ''' Start at most `max` machines per data center '''
    try:
        InstanceManager.make().start_instances(max)
    except BenchError as e:
        Print.error(e)


@task
def stop(ctx):
    ''' Stop all machines '''
    try:
        InstanceManager.make().stop_instances()
    except BenchError as e:
        Print.error(e)


@task
def info(ctx):
    ''' Display connect information about all the available machines '''
    try:
        InstanceManager.make().print_info()
    except BenchError as e:
        Print.error(e)


@task
def install(ctx):
    ''' Install the codebase on all machines '''
    try:
        Bench(ctx).install()
    except BenchError as e:
        Print.error(e)

@task
def plot(ctx):
    ''' Plot performance using the logs generated by "fab remote" '''
    plot_params = {
        'faults': 0,
        'nodes': [10,31,64,121],
        'kappa': 4,
        'trans_delay': [0, 500,1000,2000]
    }
    try:
        Plotter.plot(plot_params)
    except PlotError as e:
        Print.error(BenchError('Failed to plot performance', e))


@task
def kill(ctx):
    ''' Stop execution on all machines '''
    try:
        Bench(ctx).kill()
    except BenchError as e:
        Print.error(e)